    row_sums = [7, 18, 5, 5, 13, 7, 27, 9, 6]
    col_sums = [6, 2, 16, 8, 14, 28, 14, 7, 2]
    n = 9

    def get_subsets(target, n):
        results = []
        def backtrack(start, current_sum, current_subset):
            if current_sum == target:
                res = [0] * n
                for idx in current_subset:
                    res[idx-1] = 1
                results.append(tuple(res))
                return
            if current_sum > target:
                return
            for i in range(start, n + 1):
                backtrack(i + 1, current_sum + i, current_subset + [i])
        backtrack(1, 0, [])
        return results

    row_possibilities = [get_subsets(rs, n) for rs in row_sums]

    solution = [None] * n
    def find_grid(row_idx, current_col_sums):
        if row_idx == n:
            if all(current_col_sums[j] == col_sums[j] for j in range(n)):
                return True
            return False

        for combo in row_possibilities[row_idx]:
            new_col_sums = list(current_col_sums)
            valid = True
            for j in range(n):
                if combo[j] == 1:
                    new_col_sums[j] += (row_idx + 1)
                if new_col_sums[j] > col_sums[j]:
                    valid = False
                    break

            # Optimization: Check if remaining rows can satisfy col_sums
            if valid:
                remaining_rows_sum = sum(range(row_idx + 2, n + 1))
                for j in range(n):
                    if new_col_sums[j] + remaining_rows_sum < col_sums[j]:
                        valid = False
                        break

            if valid:
                solution[row_idx] = combo
                if find_grid(row_idx + 1, new_col_sums):
                    return True
        return False

    if find_grid(0, [0]*n):
        for row in solution:
            print(" ".join(map(str, row)))
    else:
        print("No solution")

solve()"}

